python3 <<'EOF'
import struct
from pathlib import Path

def find_png_copyright(data):
    """Look for copyright in PNG chunks"""
    i = 8  # Skip PNG signature
    while i < len(data) - 8:
        try:
            chunk_len = struct.unpack('>I', data[i:i+4])[0]
            chunk_type = data[i+4:i+8]
            chunk_data = data[i+8:i+8+chunk_len]

            if chunk_type in [b'tEXt', b'iTXt', b'zTXt']:
                # Parse tEXt
                if chunk_type == b'tEXt':
                    null_idx = chunk_data.find(b'\x00')
                    if null_idx > 0:
                        keyword = chunk_data[:null_idx].decode('latin-1')
                        value = chunk_data[null_idx+1:].decode('latin-1', errors='ignore')
                        if 'copyright' in keyword.lower():
                            return f"{keyword}: {value}"

            i += 12 + chunk_len
        except:
            break
    return None

path = Path('relist/tote_flatlay.png')
data = path.read_bytes()
result = find_png_copyright(data)
if result:
    print(f"✓ Shop credit PRESERVED in {path.name}:")
    print(f"  {result}")
else:
    print(f"❌ WARNING: Shop credit NOT FOUND in {path.name}")
